SELECT b.SEC_SNAME AS `股票名称`, b.COMB_SYMBOL AS `股票代码`, a.ENDDATE AS `报告期`, ROUND(SUM(a.HOLD_PCT), 2) AS `合计持股比例（%）` FROM GET_STK_SHR_CLS_DTL a JOIN GET_A_SEC_CODE b ON a.COMCODE = b.COMCODE WHERE a.ISVALID = 1 AND b.ISVALID = 1 AND b.SEC_SNAME LIKE '%恒瑞医药%' AND a.ENDDATE = (SELECT MAX(ENDDATE) FROM GET_STK_SHR_CLS_DTL WHERE COMCODE = a.COMCODE AND ENDDATE >= '2026-06-30 00:00:00.000' AND ENDDATE < '2026-09-30 00:00:00.000') AND a.`RANK` <= 10 GROUP BY b.SEC_SNAME, b.COMB_SYMBOL, a.ENDDATE;
